def judge(job):
  tests = cache.get(job.problem_id, job.test_version)   # verify sha256
  art = compiler.compile(job.language, job.code)
  if art.error: return Verdict('CE', msg=truncate(art.error, 4096))
  tl = problem.time_limit_ms * multiplier[job.language]
  max_t = max_m = 0
  for i, t in enumerate(sorted(tests, key=size)):
    sb = Sandbox.create(cpu_ms=tl, mem_mb=problem.mem, pids=64, net=False)
    r = sb.run(art.cmd, stdin=t.input, out_limit=64 << 20)
    sb.destroy()
    max_t = max(max_t, r.cpu_ms); max_m = max(max_m, r.peak_mem)
    if r.killed_cpu: return Verdict('TLE', test=i)
    if r.oom: return Verdict('MLE', test=i)
    if r.exit_code != 0: return Verdict('RE', test=i)
    if not checker.check(t.input, t.expected, r.stdout): return Verdict('WA', test=i)
  return Verdict('AC', time=max_t, mem=max_m)

def fingerprints(code, k=5, w=4):
  toks = normalize_tokens(code)
  hs = [hash(toks[i:i+k]) for i in range(len(toks)-k+1)]
  return {min(hs[i:i+w]) for i in range(len(hs)-w+1)}
def similar(a, b):
  fa, fb = fingerprints(a), fingerprints(b)
  return len(fa & fb) / max(1, len(fa | fb))
